test('a pin is private, validated and removable', () => {
  const state = fs.mkdtempSync(path.join(os.tmpdir(), 'clouseau-pin-'));
  try {
    const key = pinning.pinKey({head: 'a'});
    assert.equal(pinning.readPin(state, key), null);
    pinning.writePin(state, key, {sha: 'a'.repeat(40), digest: 'b'.repeat(64)});
    assert.deepEqual(pinning.readPin(state, key), {reviewer_sha: 'a'.repeat(40), reviewer_digest: 'b'.repeat(64)});
    assert.equal(fs.statSync(path.join(state, 'pins', `${key}.json`)).mode & 0o077, 0);
    pinning.clearPin(state, key); assert.equal(pinning.readPin(state, key), null);
    write(path.join(state, 'pins', `${key}.json`), JSON.stringify({reviewer_sha: 'x', reviewer_digest: 'y'}));
    assert.throws(() => pinning.readPin(state, key), /Invalid engine pin.*--engine latest/);
    write(path.join(state, 'pins', `${key}.json`), JSON.stringify({reviewer_sha: 'a'.repeat(40), reviewer_digest: 'b'.repeat(64), notified: 'x'}));
    assert.throws(() => pinning.readPin(state, key), /Invalid engine pin/);
  } finally {fs.rmSync(state, {recursive: true, force: true});}
});

test('only an unmodified checkout the installer made from its own source, with the recorded bytes, is runnable', () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'clouseau-pin-cache-'));
  try {
    const {cache, checkout, pin, origin} = installedCache(root);
    assert.equal(pinning.verifiedRevision(cache, pin), checkout);
    assert.throws(() => pinning.verifiedRevision(cache, {...pin, reviewer_sha: 'c'.repeat(40)}), /not in the local cache.*--engine latest/);
    assert.throws(() => pinning.verifiedRevision(cache, {...pin, reviewer_digest: 'd'.repeat(64)}), /different from the verified engine bytes/);
    // A checkout that is not a worktree of the cached source is refused even if it is clean and the right revision.
    const sha = pin.reviewer_sha;
    fs.rmSync(checkout, {recursive: true}); git(root, ['clone', '-q', origin, checkout]);
    assert.throws(() => pinning.verifiedRevision(cache, pin), /not an unmodified installation/);
    // A modified or wrong-revision checkout is refused.
    fs.rmSync(checkout, {recursive: true}); git(cache, ['--git-dir', path.join(cache, 'source.git'), 'worktree', 'prune']);

    git(cache, ['--git-dir', path.join(cache, 'source.git'), 'worktree', 'add', '-q', '--detach', checkout, sha]);
    assert.equal(pinning.verifiedRevision(cache, pin), checkout);
    write(path.join(checkout, 'src/a.cjs'), 'tampered');
    assert.throws(() => pinning.verifiedRevision(cache, pin), /not an unmodified installation/);
    git(checkout, ['checkout', '-q', '--', '.']);
    git(checkout, ['-c', 'user.name=t', '-c', 'user.email=t@t', 'commit', '-q', '--allow-empty', '-m', 'moved']);
    assert.throws(() => pinning.verifiedRevision(cache, pin), /not an unmodified installation/);
  } finally {fs.rmSync(root, {recursive: true, force: true});}
});

test('a continuation is re-executed verbatim on the pinned engine, without the escape flag', () => {
  assert.deepEqual(pinning.argvFor({command: 'review', directory: '/r', engine: 'latest', agent: 'claude'}), ['review', '--directory', '/r', '--agent', 'claude']);
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'clouseau-pin-exec-'));
  try {
    for (const [status, ok] of [[0, true], [2, true], [3, true], [1, false]]) {
      write(path.join(root, 'bin/clouseau.cjs'), `process.stdout.write(JSON.stringify({argv: process.argv.slice(2)}));process.exitCode=${status};`);
      if (ok) assert.deepEqual(pinning.execute(root, ['review', '--agent', 'claude']), {argv: ['review', '--agent', 'claude']});
      else assert.throws(() => pinning.execute(root, ['review']), /Pinned Clouseau engine failed \(status 1\)/);
    }
  } finally {fs.rmSync(root, {recursive: true, force: true});}
});

test('a pinned engine that cannot even start is a failure, not a result', () => {
  assert.throws(() => pinning.execute('/nonexistent-clouseau-engine', ['review'], () => ({status: null})), /status null/);
});

test('the newer-engine notice is owed once per newer revision, then remembered in the pin', () => {
  const state = fs.mkdtempSync(path.join(os.tmpdir(), 'clouseau-pin-notice-'));
  try {
    const key = pinning.pinKey({head: 'n'});
    pinning.writePin(state, key, {sha: 'a'.repeat(40), digest: 'b'.repeat(64)});
    const pin = pinning.readPin(state, key);
    assert.equal(pinning.noticeOwed(pin, 'c'.repeat(40)), true);
    pinning.markNotified(state, key, pin, 'c'.repeat(40));
    const noted = pinning.readPin(state, key);
    assert.deepEqual(noted, {reviewer_sha: 'a'.repeat(40), reviewer_digest: 'b'.repeat(64), notified: 'c'.repeat(40)});
    assert.equal(fs.statSync(path.join(state, 'pins', `${key}.json`)).mode & 0o077, 0);
    assert.equal(pinning.noticeOwed(noted, 'c'.repeat(40)), false, 'the same newer revision is not announced again');
    assert.equal(pinning.noticeOwed(noted, 'd'.repeat(40)), true, 'a revision newer still is');
  } finally {fs.rmSync(state, {recursive: true, force: true});}

'use strict';
const {test} = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const {fixture, harness} = require('../test/bootstrap-cli-fixture.cjs');
const normal = require('./local-cli.cjs');
const cli = require('./installation-cli.cjs');
const bootstrap = require('./installation-bootstrap.cjs');

// Stand-in for a fresh subagent: answers each frozen request from its own prompt and schema files.
function subagent(request) {
  const prompt = fs.readFileSync(request.prompt_file, 'utf8');
  const schema = JSON.parse(fs.readFileSync(request.schema_file, 'utf8'));
  if (request.phase === 'investigation') {
    const report = JSON.parse(prompt.slice(prompt.search(/\n\{\n/) + 1)).template;
    report.gates.forEach(gate => {gate.state = 'satisfied';});
    return {kind: 'report', report, request_sources: []};
  }
  return {answers: Object.fromEntries(Object.keys(schema.properties.answers.properties)
    .map(id => [id, id.includes('_excess_') ? 'level0' : 'level4']))};
}
const answer = (waiting, session) => {
  fs.writeFileSync(waiting.answer_file, JSON.stringify(subagent(JSON.parse(fs.readFileSync(waiting.request_file, 'utf8')))));
  return require('./local-agent.cjs').respond({request: waiting.request_file, answer: waiting.answer_file, session});
};

test('installation-review runs agent-driven: one verification, one attempt, resumable, and a verifiable installation receipt', () => fixture(async f => {
  let verifications = 0;
  const runtime = {...f.reviewRuntime, ask: async () => {throw new Error('Agent mode must not use a headless harness');},
    verify: () => {verifications++; return {fixture_only: true, exact_coverage: {lines: [1, 1], branches: [2, 2]}};}};
  const argv = ['installation-review', '--directory', f.directory, '--manifest', f.manifestFile,
    '--grant-comment', String(f.grant.comment_id), '--agent', 'claude'];
  let result; let answered = 0;
  for (let step = 0; step < 12; step++) {
    result = await normal.main(argv, runtime);
    if (result.status !== 'awaiting_agent') break;
    assert.equal(result.agent, 'claude'); assert.equal(result.installation_only, true); assert.equal(result.provider_api_calls, 0);
    assert.match(result.respond, /clouseau respond --agent-request/);
    assert.ok(result.request_file.startsWith(f.state), 'exchange evidence stays outside the checkout');

    .map(name => JSON.parse(fs.readFileSync(path.join(directory, name), 'utf8')).session).filter(Boolean);
}

function createExchange({directory, agent, journal}) {
  if (!AGENTS.includes(agent)) fail(`Supported agent harnesses: ${AGENTS.join(', ')}`);
  fs.mkdirSync(directory, {recursive: true, mode: 0o700});
  let sequence = 0;
  async function ask(task) {
    sequence++;
    const id = padded(sequence);
    const requestPath = path.join(directory, `request-${id}.json`);
    const schemaPath = path.join(directory, `schema-${id}.json`);
    const promptPath = path.join(directory, `prompt-${id}.txt`);
    const responsePath = path.join(directory, `response-${id}.json`);
    const consumed = path.join(directory, `consumed-${id}`);
    const answerFile = path.join(directory, `answer-${id}.json`);
    const requestDigest = digest({schema: task.schema, prompt: task.prompt});
    if (fs.existsSync(requestPath)) {
      const stored = JSON.parse(fs.readFileSync(requestPath, 'utf8'));
      if (stored.request_digest !== requestDigest || stored.role !== task.role || stored.phase !== task.phase) {
        fail(`Agent exchange diverged at session ${sequence}; the frozen evidence changed. Evidence preserved in ${directory}`);
      }
    } else {
      fs.writeFileSync(schemaPath, JSON.stringify(shareSchema(task.schema)), {mode: 0o600});
      fs.writeFileSync(promptPath, readablePrompt(task.prompt), {mode: 0o600});
      fs.writeFileSync(requestPath, JSON.stringify({version: 1, sequence, agent, role: task.role, phase: task.phase,
        request_digest: requestDigest, prompt_file: promptPath, schema_file: schemaPath, answer_file: answerFile,
        instructions: INSTRUCTIONS}, null, 2) + '\n', {mode: 0o600});
      journal({role: task.role, phase: task.phase, status: 'started', request_digest: requestDigest, execution: 'agent_session'});
    }
    const rejected = fs.readdirSync(directory).filter(name => name.startsWith(`rejected-${id}-`)).length;
    if (rejected >= MAX_REJECTIONS) fail(`Agent answer ${sequence} was rejected ${rejected} times; review stopped. Evidence preserved in ${directory}`);
    if (!fs.existsSync(responsePath)) {
      throw new AwaitingAgent({agent, sequence, role: task.role, phase: task.phase, request_file: requestPath,
        prompt_file: promptPath, schema_file: schemaPath, answer_file: answerFile, rejections: rejected});
    }
    const {text, value: response} = readJson(responsePath, 'Agent response');
    if (response.request_digest !== requestDigest || response.agent !== agent || !SESSION.test(response.session)) {
      fail(`Agent response ${sequence} does not match its request`);
    }

    validateValue(task.schema, response.value);
    if (task.check) {
      try {task.check(response.value);} catch (error) {
        // A semantically invalid answer is returned to the agent for correction; its session stays spent.
        fs.writeFileSync(path.join(directory, `rejected-${id}-${rejected + 1}.json`),
          JSON.stringify({session: response.session, reason: error.message}) + '\n', {mode: 0o600});
        fs.unlinkSync(responsePath);
        throw new AwaitingAgent({agent, sequence, role: task.role, phase: task.phase, request_file: requestPath,
          prompt_file: promptPath, schema_file: schemaPath, answer_file: answerFile, rejections: rejected + 1,
          reason: `The previous answer was rejected: ${error.message}`});
      }
    }
    const provenance = {harness: agent, execution: 'agent_session', role: task.role, phase: task.phase,
      session: response.session, request_digest: requestDigest, response_digest: digest(response.value),
      transport_digest: digest(text)};
    if (!fs.existsSync(consumed)) {
      fs.writeFileSync(consumed, '', {mode: 0o600});
      journal({role: task.role, phase: task.phase, value: response.value, provenance});
    }
    return {value: response.value, provenance};
  }
  return {ask};
}

function respond({request, answer, session}) {
  if (!request || !answer || !session) fail('respond requires --agent-request, --answer and --session');
  const requestPath = path.resolve(request);
  const directory = path.dirname(requestPath);
  const match = REQUEST.exec(path.basename(requestPath));
  if (!match || path.basename(directory) !== 'agent') fail('The request must be a Clouseau agent request file');
  const stored = readJson(requestPath, 'Agent request').value;
  if (stored.version !== 1 || path.resolve(stored.answer_file || '') !== path.join(directory, `answer-${match[1]}.json`) ||
    !AGENTS.includes(stored.agent)) fail('Invalid agent request file');
  if (!SESSION.test(session)) fail(`Invalid session identifier. ${SESSION_RULE}`);
  const responsePath = path.join(directory, `response-${match[1]}.json`);
  if (fs.existsSync(responsePath)) fail('This agent request already has an accepted response');
  if (sessions(directory).includes(session)) fail('A session cannot answer two requests; start a fresh session');
  const answerPath = path.resolve(answer);
  if (answerPath !== path.resolve(stored.answer_file)) fail('Write the answer to the answer_file named by the request');
  const rejections = fs.readdirSync(directory).filter(name => name.startsWith(`rejected-${match[1]}-`)).length;

}

test('schema validation accepts the supported subset and fails closed on anything else', () => {
  const schema = {type: 'object', properties: {kind: {type: 'string', enum: ['a', 'b']}, items: {type: 'array', maxItems: 2, items: {type: 'integer', minimum: 0}},
